                </Button>
              </div>
            </Card>

            {/* Stats Grid */}
            <Card className="md:col-span-2 p-6">
              <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-4 flex items-center">
                <Crown className="w-5 h-5 mr-2 text-yellow-500" />
