                  </p>
                  <p className="text-sm text-gray-500 dark:text-gray-400">Total XP</p>
                </div>
                <div className="text-center p-4 bg-orange-50 dark:bg-orange-900/20 rounded-xl">
                  <Flame className="w-6 h-6 text-orange-500 mx-auto mb-2" />
                  <p className="text-2xl font-bold text-gray-900 dark:text-white">
                    {displayUser.streak || 0}
                  </p>
                  <p className="text-sm text-gray-500 dark:text-gray-400">Day Streak</p>
                </div>
                <div className="text-center p-4 bg-green-50 dark:bg-green-900/20 rounded-xl">
                  <BookOpen className="w-6 h-6 text-green-500 mx-auto mb-2" />
                  <p className="text-2xl font-bold text-gray-900 dark:text-white">
                    {displayUser.totalLessonsCompleted || 0}
                  </p>
                  <p className="text-sm text-gray-500 dark:text-gray-400">Lessons</p>
                </div>
                <div className="text-center p-4 bg-purple-50 dark:bg-purple-900/20 rounded-xl">
                  <Award className="w-6 h-6 text-purple-500 mx-auto mb-2" />
                  <p className="text-2xl font-bold text-gray-900 dark:text-white">
                    {displayUser.level || 1}
                  </p>
                  <p className="text-sm text-gray-500 dark:text-gray-400">Level</p>
                </div>
              </div>
            </Card>
          </div>

          {/* Badges & Achievements */}
          <div className="grid md:grid-cols-2 gap-6">
            {/* Badges */}
            <Card className="p-6">
              <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-4">
                Badges Earned
              </h3>
              {displayUser.badges && displayUser.badges.length > 0 ? (
                <div className="flex flex-wrap gap-2">
                  {displayUser.badges.map((badge, index) => (
                    <Badge key={index} variant="secondary" className="px-3 py-1">
                      <Award className="w-3 h-3 mr-1" />
                      {badge}
                    </Badge>
                  ))}
                </div>
              ) : (
                <p className="text-gray-500 dark:text-gray-400 text-center py-4">
                  No badges yet. Start learning to earn badges!
                </p>
              )}
            </Card>

            {/* Quick Actions */}
            <Card className="p-6">
              <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-4">
                Quick Actions
              </h3>
              <div className="space-y-2">
                <Button 
                  variant="outline" 
                  className="w-full justify-between"
                  onClick={() => navigate('/settings')}
                >
                  <span className="flex items-center">
                    <Settings className="w-4 h-4 mr-2" />
                    Settings
                  </span>
                  <ChevronRight className="w-4 h-4" />
                </Button>
                <Button 
                  variant="outline" 
                  className="w-full justify-between"
                  onClick={() => navigate('/lessons')}
                >
                  <span className="flex items-center">
                    <BookOpen className="w-4 h-4 mr-2" />
                    Continue Learning
                  </span>
                  <ChevronRight className="w-4 h-4" />
                </Button>
              </div>
            </Card>
          </div>
        </motion.div>
      </div>
    </div>
  );
}

import { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Button } from '@/app/components/ui/button';
