import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { Button } from '@/app/components/ui/button';
import { Card } from '@/app/components/ui/card';
import { Input } from '@/app/components/ui/input';
import { Label } from '@/app/components/ui/label';
import { motion } from 'motion/react';
import { Mail, Lock, User as UserIcon, AlertCircle, Loader2, CheckCircle } from 'lucide-react';
import { useAuthStore } from '@/store/authStore';
import type { UserRole } from '@/types/auth';

export function Register() {
  const navigate = useNavigate();
  const { register, isLoading, user, isAuthenticated } = useAuthStore();
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [selectedRole, setSelectedRole] = useState<UserRole>('student');
  const [error, setError] = useState('');

  // Redirect if already authenticated
  useEffect(() => {
    if (isAuthenticated && user) {
      console.log('[Register] User already authenticated, redirecting to dashboard:', user.role);
      const dashboardRoute = user.role === 'teacher' ? '/teacher' : user.role === 'admin' ? '/admin' : '/';
      navigate(dashboardRoute, { replace: true });
    }
  }, [isAuthenticated, user, navigate]);

  const roles = [
    { 
      id: 'student' as UserRole, 
      title: 'Student', 
      description: 'Learn English with AI',
      color: 'from-green-400 to-green-600',
    },
    { 
      id: 'teacher' as UserRole, 
      title: 'Teacher', 
      description: 'Teach and manage classes',
      color: 'from-blue-400 to-blue-600',
    },
    { 
      id: 'admin' as UserRole, 
      title: 'Admin', 
      description: 'Manage platform',
      color: 'from-purple-400 to-purple-600',
    },
  ];

  const validateForm = () => {
    if (!name.trim()) {
      setError('Please enter your name');
      return false;
    }
    if (!email.trim() || !email.includes('@')) {
      setError('Please enter a valid email');
      return false;
    }
    if (password.length < 6) {
      setError('Password must be at least 6 characters');
      return false;
    }
    if (password !== confirmPassword) {
      setError('Passwords do not match');
      return false;
    }
    return true;
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    if (!validateForm()) return;

    try {
      await register(name, email, password, selectedRole);

      // Get the updated state from store after auto-login
      const user = useAuthStore.getState().user;
      const role = user?.role;

      if (role === 'teacher') {
        navigate('/teacher');
      } else if (role === 'admin') {
        navigate('/admin');
      } else {
        navigate('/');
      }
    } catch (err: any) {
      setError(err.message || 'Registration failed. Please try again.');
    }
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-green-50 via-blue-50 to-purple-50 dark:from-gray-900 dark:via-gray-900 dark:to-gray-900 flex items-center justify-center p-4">
      <div className="max-w-4xl w-full">
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.5 }}
          className="text-center mb-8"
        >
          {/* Logo */}
          <motion.div
            initial={{ scale: 0 }}
            animate={{ scale: 1 }}
            transition={{ delay: 0.2, type: 'spring', stiffness: 200 }}
            className="flex justify-center mb-6"
          >
            <div className="flex h-16 w-16 items-center justify-center rounded-3xl bg-gradient-to-br from-green-400 to-green-600 text-white font-bold shadow-2xl text-3xl">
              E
            </div>
          </motion.div>

          <h1 className="text-3xl md:text-4xl font-bold text-gray-900 dark:text-white mb-2">
            Create your account
          </h1>
          <p className="text-lg text-gray-600 dark:text-gray-300">
            Join thousands of learners improving their English
          </p>
        </motion.div>

        <div className="grid md:grid-cols-5 gap-8">
          {/* Role Selection */}
          <motion.div
            initial={{ opacity: 0, x: -20 }}
            animate={{ opacity: 1, x: 0 }}
            transition={{ delay: 0.3 }}
            className="md:col-span-2"
          >
            <h2 className="text-xl font-bold text-gray-900 dark:text-white mb-4">
              I am a...
            </h2>
            <div className="space-y-3">
              {roles.map((role, index) => (
                <motion.div
                  key={role.id}
                  initial={{ opacity: 0, x: -10 }}
                  animate={{ opacity: 1, x: 0 }}
                  transition={{ delay: 0.4 + index * 0.1 }}
                >
                  <Card
                    className={`p-4 cursor-pointer transition-all duration-300 ${
                      selectedRole === role.id
                        ? 'ring-2 ring-green-500 shadow-lg'
                        : 'hover:shadow-md'
                    }`}
                    onClick={() => setSelectedRole(role.id)}
                  >
                    <div className="flex items-start gap-3">
                      <div className={`flex h-12 w-12 items-center justify-center rounded-2xl bg-gradient-to-br ${role.color} text-white font-bold shadow-lg flex-shrink-0`}>
                        {role.title[0]}
                      </div>
                      <div className="flex-1">
                        <div className="flex items-center gap-2">
                          <h3 className="font-semibold text-gray-900 dark:text-white">
                            {role.title}
                          </h3>
                          {selectedRole === role.id && (
                            <CheckCircle className="h-5 w-5 text-green-500" />
                          )}
                        </div>
                        <p className="text-sm text-gray-600 dark:text-gray-400">
                          {role.description}
                        </p>
                      </div>
                    </div>
                  </Card>
                </motion.div>
              ))}
            </div>
          </motion.div>

          {/* Registration Form */}
          <motion.div
            initial={{ opacity: 0, x: 20 }}
            animate={{ opacity: 1, x: 0 }}
            transition={{ delay: 0.3 }}
            className="md:col-span-3"
          >
            <Card className="p-8">
              <form onSubmit={handleSubmit} className="space-y-5">
                <div>
                  <Label htmlFor="name">Full Name</Label>
                  <div className="relative mt-2">
                    <UserIcon className="absolute left-3 top-1/2 -translate-y-1/2 h-5 w-5 text-gray-400" />
                    <Input
                      id="name"
                      type="text"
                      placeholder="John Doe"
                      value={name}
                      onChange={(e) => setName(e.target.value)}
                      className="pl-10 rounded-xl"
                      disabled={isLoading}
                    />
                  </div>
                </div>

                <div>
                  <Label htmlFor="email">Email</Label>
                  <div className="relative mt-2">
                    <Mail className="absolute left-3 top-1/2 -translate-y-1/2 h-5 w-5 text-gray-400" />
                    <Input
                      id="email"
                      type="email"
                      placeholder="your@email.com"
                      value={email}
                      onChange={(e) => setEmail(e.target.value)}
                      className="pl-10 rounded-xl"
                      disabled={isLoading}
                    />
                  </div>
                </div>

                <div>
                  <Label htmlFor="password">Password</Label>
                  <div className="relative mt-2">
                    <Lock className="absolute left-3 top-1/2 -translate-y-1/2 h-5 w-5 text-gray-400" />
                    <Input
                      id="password"
                      type="password"
                      placeholder="At least 6 characters"
                      value={password}
                      onChange={(e) => setPassword(e.target.value)}
                      className="pl-10 rounded-xl"
                      disabled={isLoading}
                    />
                  </div>
                </div>

                <div>
                  <Label htmlFor="confirmPassword">Confirm Password</Label>
                  <div className="relative mt-2">
                    <Lock className="absolute left-3 top-1/2 -translate-y-1/2 h-5 w-5 text-gray-400" />
                    <Input
                      id="confirmPassword"
                      type="password"
                      placeholder="Confirm your password"
                      value={confirmPassword}
                      onChange={(e) => setConfirmPassword(e.target.value)}
                      className="pl-10 rounded-xl"
                      disabled={isLoading}
                    />
                  </div>
                </div>

                {error && (
                  <motion.div
                    initial={{ opacity: 0, y: -10 }}
                    animate={{ opacity: 1, y: 0 }}
                    className="flex items-center gap-2 p-3 bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 rounded-xl text-red-600 dark:text-red-400"
                  >
                    <AlertCircle className="h-5 w-5 flex-shrink-0" />
                    <p className="text-sm">{error}</p>
                  </motion.div>
                )}

                <Button
                  type="submit"
                  size="lg"
                  disabled={isLoading}
                  className="w-full bg-green-500 hover:bg-green-600 text-white rounded-xl py-6 text-lg shadow-lg hover:shadow-xl transition-all"
                >
                  {isLoading ? (
                    <>
                      <Loader2 className="mr-2 h-5 w-5 animate-spin" />
                      Creating account...
                    </>
                  ) : (
                    'Create Account'
                  )}
                </Button>

                <div className="text-center">
                  <button
                    type="button"
                    onClick={() => navigate('/login')}
                    className="text-green-600 dark:text-green-400 hover:underline"
                  >
                    Already have an account? Sign in
                  </button>
                </div>
              </form>
            </Card>
          </motion.div>
        </div>

        {/* Back to Welcome */}
        <motion.div
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ delay: 0.7 }}
          className="text-center mt-6"
        >
          <button
            onClick={() => navigate('/')}
            className="text-gray-600 dark:text-gray-400 hover:text-gray-900 dark:hover:text-white transition-colors"
          >
            ← Back to Welcome
          </button>
        </motion.div>
      </div>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { Button } from '@/app/components/ui/button';
import { Card } from '@/app/components/ui/card';
import { Input } from '@/app/components/ui/input';
import { Label } from '@/app/components/ui/label';
import { motion } from 'motion/react';
import { Mail, Lock, User as UserIcon, AlertCircle, Loader2, CheckCircle } from 'lucide-react';
import { useAuthStore } from '@/store/authStore';
import { getErrorMessage, logError } from '@/utils/errorHandler';
import type { UserRole } from '@/types/auth';

export function Register() {
  const navigate = useNavigate();
  const { register, isLoading, user, isAuthenticated } = useAuthStore();
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [selectedRole, setSelectedRole] = useState<UserRole>('student');
  const [error, setError] = useState('');

  // Redirect if already authenticated
  useEffect(() => {
    if (isAuthenticated && user) {
      console.log('[Register] User already authenticated, redirecting to dashboard:', user.role);
      const dashboardRoute = user.role === 'teacher' ? '/teacher' : user.role === 'admin' ? '/admin' : '/';
      navigate(dashboardRoute, { replace: true });
    }
  }, [isAuthenticated, user, navigate]);

  const roles = [
    { 
      id: 'student' as UserRole, 
      title: 'Student', 
      description: 'Learn English with AI',
      color: 'from-green-400 to-green-600',
    },
    { 
      id: 'teacher' as UserRole, 
      title: 'Teacher', 
      description: 'Teach and manage classes',
      color: 'from-blue-400 to-blue-600',
    },
    { 
      id: 'admin' as UserRole, 
      title: 'Admin', 
      description: 'Manage platform',
      color: 'from-purple-400 to-purple-600',
    },
  ];

  const validateForm = () => {
    if (!name.trim()) {
      setError('Please enter your name');
      return false;
    }
    if (!email.trim() || !email.includes('@')) {
      setError('Please enter a valid email');
      return false;
    }
    if (password.length < 6) {
      setError('Password must be at least 6 characters');
      return false;
    }
    if (password !== confirmPassword) {
      setError('Passwords do not match');
      return false;
    }
    return true;
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    if (!validateForm()) return;

    try {
      await register(name, email, password, selectedRole);

      // Get the updated state from store after auto-login
      const user = useAuthStore.getState().user;
      const role = user?.role;

      if (role === 'teacher') {
        navigate('/teacher');
      } else if (role === 'admin') {
        navigate('/admin');
      } else {
        navigate('/');
      }
    } catch (err: any) {
      logError('Register', err, { email });
      const errorMsg = getErrorMessage(err, 'Registration failed. Please try again.');
      setError(errorMsg);
    }
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-green-50 via-blue-50 to-purple-50 dark:from-gray-900 dark:via-gray-900 dark:to-gray-900 flex items-center justify-center p-4">
      <div className="max-w-4xl w-full">
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.5 }}
          className="text-center mb-8"
        >
          {/* Logo */}
          <motion.div
            initial={{ scale: 0 }}
            animate={{ scale: 1 }}
            transition={{ delay: 0.2, type: 'spring', stiffness: 200 }}
            className="flex justify-center mb-6"
          >
            <div className="flex h-16 w-16 items-center justify-center rounded-3xl bg-gradient-to-br from-green-400 to-green-600 text-white font-bold shadow-2xl text-3xl">
              E
            </div>
          </motion.div>

          <h1 className="text-3xl md:text-4xl font-bold text-gray-900 dark:text-white mb-2">
            Create your account
          </h1>
          <p className="text-lg text-gray-600 dark:text-gray-300">
            Join thousands of learners improving their English
          </p>
        </motion.div>

        <div className="grid md:grid-cols-5 gap-8">
          {/* Role Selection */}
          <motion.div
            initial={{ opacity: 0, x: -20 }}
            animate={{ opacity: 1, x: 0 }}
            transition={{ delay: 0.3 }}
            className="md:col-span-2"
          >
            <h2 className="text-xl font-bold text-gray-900 dark:text-white mb-4">
              I am a...
            </h2>
            <div className="space-y-3">
              {roles.map((role, index) => (
                <motion.div
                  key={role.id}
                  initial={{ opacity: 0, x: -10 }}
                  animate={{ opacity: 1, x: 0 }}
                  transition={{ delay: 0.4 + index * 0.1 }}
                >
                  <Card
                    className={`p-4 cursor-pointer transition-all duration-300 ${
                      selectedRole === role.id
                        ? 'ring-2 ring-green-500 shadow-lg'
                        : 'hover:shadow-md'
                    }`}
                    onClick={() => setSelectedRole(role.id)}
                  >
                    <div className="flex items-start gap-3">
                      <div className={`flex h-12 w-12 items-center justify-center rounded-2xl bg-gradient-to-br ${role.color} text-white font-bold shadow-lg flex-shrink-0`}>
                        {role.title[0]}
                      </div>
                      <div className="flex-1">
                        <div className="flex items-center gap-2">
                          <h3 className="font-semibold text-gray-900 dark:text-white">
                            {role.title}
                          </h3>
                          {selectedRole === role.id && (
                            <CheckCircle className="h-5 w-5 text-green-500" />
                          )}
                        </div>
                        <p className="text-sm text-gray-600 dark:text-gray-400">
                          {role.description}
                        </p>
                      </div>
                    </div>
                  </Card>
                </motion.div>
              ))}
            </div>
          </motion.div>

          {/* Registration Form */}
          <motion.div
            initial={{ opacity: 0, x: 20 }}
            animate={{ opacity: 1, x: 0 }}
            transition={{ delay: 0.3 }}
            className="md:col-span-3"
          >
            <Card className="p-8">
              <form onSubmit={handleSubmit} className="space-y-5">
                <div>
                  <Label htmlFor="name">Full Name</Label>
                  <div className="relative mt-2">
                    <UserIcon className="absolute left-3 top-1/2 -translate-y-1/2 h-5 w-5 text-gray-400" />
                    <Input
                      id="name"
                      type="text"
                      placeholder="John Doe"
                      value={name}
                      onChange={(e) => setName(e.target.value)}
                      className="pl-10 rounded-xl"
                      disabled={isLoading}
                    />
                  </div>
                </div>

                <div>
                  <Label htmlFor="email">Email</Label>
                  <div className="relative mt-2">
                    <Mail className="absolute left-3 top-1/2 -translate-y-1/2 h-5 w-5 text-gray-400" />
                    <Input
                      id="email"
                      type="email"
                      placeholder="your@email.com"
                      value={email}
                      onChange={(e) => setEmail(e.target.value)}
                      className="pl-10 rounded-xl"
                      disabled={isLoading}
                    />
                  </div>
                </div>

                <div>
                  <Label htmlFor="password">Password</Label>
                  <div className="relative mt-2">
                    <Lock className="absolute left-3 top-1/2 -translate-y-1/2 h-5 w-5 text-gray-400" />
                    <Input
                      id="password"
                      type="password"
                      placeholder="At least 6 characters"
                      value={password}
                      onChange={(e) => setPassword(e.target.value)}
                      className="pl-10 rounded-xl"
                      disabled={isLoading}
                    />
                  </div>
                </div>

                <div>
                  <Label htmlFor="confirmPassword">Confirm Password</Label>
                  <div className="relative mt-2">
                    <Lock className="absolute left-3 top-1/2 -translate-y-1/2 h-5 w-5 text-gray-400" />
                    <Input
                      id="confirmPassword"
                      type="password"
                      placeholder="Confirm your password"
                      value={confirmPassword}
                      onChange={(e) => setConfirmPassword(e.target.value)}
                      className="pl-10 rounded-xl"
                      disabled={isLoading}
                    />
                  </div>
                </div>

                {error && (
                  <motion.div
                    initial={{ opacity: 0, y: -10 }}
                    animate={{ opacity: 1, y: 0 }}
                    className="flex items-center gap-2 p-3 bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 rounded-xl text-red-600 dark:text-red-400"
                  >
                    <AlertCircle className="h-5 w-5 flex-shrink-0" />
                    <p className="text-sm">{error}</p>
                  </motion.div>
                )}

                <Button
                  type="submit"
                  size="lg"
                  disabled={isLoading}
                  className="w-full bg-green-500 hover:bg-green-600 text-white rounded-xl py-6 text-lg shadow-lg hover:shadow-xl transition-all"
                >
                  {isLoading ? (
                    <>
                      <Loader2 className="mr-2 h-5 w-5 animate-spin" />
                      Creating account...
                    </>
                  ) : (
                    'Create Account'
                  )}
                </Button>

                <div className="text-center">
                  <button
                    type="button"
                    onClick={() => navigate('/login')}
                    className="text-green-600 dark:text-green-400 hover:underline"
                  >
                    Already have an account? Sign in
                  </button>
                </div>
              </form>
            </Card>
          </motion.div>
        </div>

        {/* Back to Welcome */}
        <motion.div
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ delay: 0.7 }}
          className="text-center mt-6"
        >
          <button
            onClick={() => navigate('/')}
            className="text-gray-600 dark:text-gray-400 hover:text-gray-900 dark:hover:text-white transition-colors"
          >
            ← Back to Welcome
          </button>
        </motion.div>
      </div>
    </div>
  );
}

/**
 * Authentication Store using Zustand with persistence
 * Handles user authentication state, tokens, and permissions
 */

import { create } from 'zustand';
import { persist } from 'zustand/middleware';
import type { AuthUser, UserRole, LoginCredentials } from '@/types/auth';
import axiosInstance from '@/services/axiosConfig';
import { API_BASE_URL } from '@/services/baseUrl';

interface AuthTokens {
  accessToken: string;
  refreshToken: string;
}

interface AuthState {
  user: AuthUser | null;
  tokens: AuthTokens | null;
  isAuthenticated: boolean;
  isLoading: boolean;

  // Actions
  login: (credentials: LoginCredentials) => Promise<void>;
  logout: () => void;
  register: (name: string, email: string, password: string, role: UserRole) => Promise<void>;
  updateUser: (updates: Partial<AuthUser>) => void;
  updateTokens: (tokens: AuthTokens) => void;
  checkPermission: (permission: string) => boolean;
}

// Helper function to normalize role from backend
const normalizeRole = (backendRole: string): UserRole => {
  const role = (backendRole ?? '').toString().toLowerCase();
  if (['student', 'teacher', 'admin'].includes(role)) {
    return role as UserRole;
  }
  return 'student'; // Default fallback
};

export const useAuthStore = create<AuthState>()(
  persist(
    (set, get) => ({
      user: null,
      tokens: null,
      isAuthenticated: false,
      isLoading: false,

      // LOGIN: Call BE /v1/auth/login, receive LoginResponse (user + token + refreshToken)
      login: async (credentials) => {
        set({ isLoading: true });
        try {
          const res = await axiosInstance.post(' /v1/auth/login', {
            email: credentials.email,
            password: credentials.password,
          });

          const body = res.data;
          const data = body.data as {
            user: any;
            token: string;
            refreshToken: string;
          };

          const backendRole = (data.user.role ?? '').toString().toLowerCase();
          const normalizedRole = normalizeRole(backendRole);

          const mappedUser: AuthUser = {
            id: data.user.id?.toString() ?? '',
            name: data.user.fullName ?? data.user.name ?? data.user.email,
            email: data.user.email,
            avatar: data.user.avatarUrl ?? undefined,
            role: normalizedRole,
            permissions: Array.isArray(data.user.permissions) && data.user.permissions.length > 0
              ? data.user.permissions
              : ['view:lessons'],
            // Student specific fields
            level: data.user.level,
            xp: data.user.xp,
            streak: data.user.streak,
            totalLessonsCompleted: data.user.totalLessonsCompleted,
            faceIdEnrolled: data.user.faceIdEnrolled,
            enrolledClasses: data.user.enrolledClasses,
            // Teacher specific fields
            teachingSubjects: data.user.teachingSubjects,
            // Admin specific fields
            isSuperAdmin: data.user.isSuperAdmin,
          };

          set({
            user: mappedUser,
            tokens: {
              accessToken: data.token,
              refreshToken: data.refreshToken,
            },
            isAuthenticated: true,
            isLoading: false,
          });
        } catch (error) {
          set({ isLoading: false });
          throw error;
        }
      },

      // LOGOUT: Call BE (if has token) then clear user + token on FE
      logout: () => {
        const { tokens } = get();

        if (tokens?.accessToken) {
          // Fire-and-forget, don't block UI
          axiosInstance
            .post('/v1/auth/logout')
            .catch(() => {
              // Ignore logout errors, FE still clears state
            });
        }

        set({ user: null, tokens: null, isAuthenticated: false });
      },

      // REGISTER: Call /v1/auth/register/local, then auto-login
      register: async (name, email, password, role) => {
        console.log('--- AuthStore: register start ---', { name, email, role });
        set({ isLoading: true });
        try {
          const payload = {
            fullName: name,
            email,
            password,
            role: role.toUpperCase(), // STUDENT / TEACHER
          };
          console.log('--- AuthStore: Sending request to:', `${API_BASE_URL}/v1/auth/register/local`);
          console.log('--- AuthStore: Payload:', payload);

          await axiosInstance.post('/v1/auth/register/local', payload);

          console.log('--- AuthStore: Register success, now logging in...');
          // Auto-login after registration for better UX
          await get().login({ email, password });
          set({ isLoading: false });
        } catch (error) {
          console.error('--- AuthStore: Register exception:', error);
          set({ isLoading: false });
          throw error;
        }
      },

      updateUser: (updates) => {
        const currentUser = get().user;
        if (currentUser) {
          set({ user: { ...currentUser, ...updates } });
        }
      },

      updateTokens: (tokens) => {
        set({ tokens });
      },

      checkPermission: (permission) => {
        const user = get().user;
        if (!user) return false;
        if (user.permissions.includes('*')) return true;
        return user.permissions.includes(permission);
      },
    }),
    {
      name: 'auth-storage',
      partialize: (state) => ({
        user: state.user,
        tokens: state.tokens,
        isAuthenticated: state.isAuthenticated,
      }),
    }
  )
);

